var handle = null;
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function paint() {
  for (var i = 0; i < groups.length; i++) {
    groups[i].textContent = shown ? full[i] : hid[i];
  }
