var numEl = root.querySelector('.bnk3-balance-tile__num');
var avail = root.querySelector('.bnk3-balance-tile__seg--avail');
var pend = root.querySelector('.bnk3-balance-tile__seg--pend');
var total = 4182.60, settled = 3958.10;
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function money(v) {
  var s = v.toFixed(2).split('.');
  return s[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',') + '.' + s[1];
}

function grow() {
  avail.style.width = (settled / total * 100).toFixed(2) + '%';
  pend.style.width = ((total - settled) / total * 100).toFixed(2) + '%';
}

if (reduce) {
  numEl.textContent = money(total);
  grow();
} else {
  var start = 0;
  var dur = 950;
  requestAnimationFrame(grow);
  requestAnimationFrame(function step(t) {
    if (!start) start = t;
    var p = Math.min(1, (t - start) / dur);
    var e = 1 - Math.pow(1 - p, 3);
    numEl.textContent = money(total * e);
    if (p < 1) requestAnimationFrame(step);
  });
}

