js:
var scroller = root.querySelector('.bnk3-txn-list__items');
var rows = root.querySelectorAll('.bnk3-txn-list__btn');

function edge() {
  var more = scroller.scrollTop + scroller.clientHeight < scroller.scrollHeight - 2;
  root.classList.toggle('bnk3-txn-list--more', more);
}

scroller.addEventListener('scroll', edge, { passive: true });
edge();

for (var i = 0; i < rows.length; i++) {
  rows[i].addEventListener('click', function () {
    for (var j = 0; j < rows.length; j++) {
      rows[j].classList.remove('bnk3-txn-list__btn--active');
      rows[j].removeAttribute('aria-current');
    }
    this.classList.add('bnk3-txn-list__btn--active');
    this.setAttribute('aria-current', 'true');
  });
}

