for (i = 0; i < radios.length; i++) { radios[i].name = uniq; }

function who() {
  for (var k = 0; k < radios.length; k++) { if (radios[k].checked) return radios[k].value; }
  return radios[0].value;
}

function value() {
  var n = parseFloat(amount.value.replace(/[^0-9.]/g, ''));
  return isNaN(n) ? 0 : n;
}

function sync() {
  if (busy) return;
  var v = value();
  var ok = v > 0 && v <= 3958.10;
  root.classList.toggle('bnk3-transfer-form--bad', amount.value.length > 0 && !ok);
