var input = root.querySelector('.bnk3-iban-input__in');
var msg = root.querySelector('.bnk3-iban-input__msg');
var cc = root.querySelector('.bnk3-iban-input__country');
var fill = root.querySelector('.bnk3-iban-input__fill');

var SPEC = {
  GB: [22, 'United Kingdom'], DE: [22, 'Germany'], FR: [27, 'France'], ES: [24, 'Spain'],
  IT: [27, 'Italy'], NL: [18, 'Netherlands'], IE: [22, 'Ireland'], PT: [25, 'Portugal'],
  BE: [16, 'Belgium'], CH: [21, 'Switzerland'], AT: [20, 'Austria'], PL: [28, 'Poland'],
  SE: [24, 'Sweden'], NO: [15, 'Norway'], DK: [18, 'Denmark'], FI: [18, 'Finland']
};

function clean(s) { return s.toUpperCase().replace(/[^0-9A-Z]/g, ''); }
function group(s) { return s.replace(/(.{4})/g, '$1 ').trim(); }

function mod97(raw) {
  var re = raw.slice(4) + raw.slice(0, 4);
  var rem = 0;
  for (var i = 0; i < re.length; i++) {
    var ch = re.charAt(i);
    var part = (ch >= 'A' && ch <= 'Z') ? String(ch.charCodeAt(0) - 55) : ch;
    for (var j = 0; j < part.length; j++) {
      rem = (rem * 10 + Number(part.charAt(j))) % 97;
    }
  }
  return rem;
}

function assess() {
  var raw = clean(input.value);
  root.classList.remove('bnk3-iban-input--ok', 'bnk3-iban-input--bad');
  var code = raw.slice(0, 2);
  var spec = SPEC[code];
  cc.textContent = raw.length >= 2 ? code : '--';

  if (raw.length === 0) {
    fill.style.width = '0%';
    msg.textContent = "Enter the recipient's international account number.";
    return;
  }
  if (raw.length < 2 || !/^[A-Z]{2}$/.test(code)) {
    fill.style.width = '4%';
    msg.textContent = 'Starts with a two-letter country code, e.g. GB or DE.';
    return;
  }
  if (!spec) {
    fill.style.width = '8%';
    root.classList.add('bnk3-iban-input--bad');
    msg.textContent = 'Country ' + code + ' is not supported for SEPA transfers.';
    return;
  }
  fill.style.width = Math.min(100, raw.length / spec[0] * 100).toFixed(1) + '%';
  if (raw.length < spec[0]) {
    msg.textContent = spec[1] + ' · ' + raw.length + ' of ' + spec[0] + ' characters.';
    return;
  }
  if (raw.length > spec[0]) {
    root.classList.add('bnk3-iban-input--bad');
    msg.textContent = spec[1] + ' IBANs are ' + spec[0] + ' characters — ' + raw.length + ' entered.';
    return;
  }
  if (mod97(raw) === 1) {
    root.classList.add('bnk3-iban-input--ok');
    msg.textContent = 'Valid · ' + spec[1] + ' · checksum passed.';
  } else {
    root.classList.add('bnk3-iban-input--bad');
    msg.textContent = 'Checksum failed — please re-check the digits.';
  }
}

input.addEventListener('input', function () {
  var caret = input.selectionStart || 0;
  var before = clean(input.value.slice(0, caret)).length;
  var raw = clean(input.value);
  input.value = group(raw);
  var seen = 0, pos = input.value.length;
  for (var i = 0; i < input.value.length; i++) {
    if (seen === before) { pos = i; break; }
    if (input.value.charAt(i) !== ' ') seen++;
  }
  if (before >= raw.length) { pos = input.value.length; }
  try { input.setSelectionRange(pos, pos); } catch (e) {}
  assess();
});

assess();

