function money(v) {
  var s = Math.abs(v).toFixed(2).split('.');
  return '£' + s[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',') + '.' + s[1];
}

function render(animate) {
  var d = DATA[idx];
  var peak = 5000;
  monthEl.textContent = d.m;
  stateEl.textContent = d.closed ? 'Ready' : 'In progress';
  root.classList.toggle('bnk3-stmt-summary--open', !d.closed);
  openEl.textContent = money(d.open);
  closeEl.textContent = money(d.open + d.inn - d.out);
  inEl.textContent = '+ ' + money(d.inn);
  outEl.textContent = '− ' + money(d.out);
  foot.textContent = d.cr + ' credits · ' + d.db + ' debits · ' + (d.closed ? 'PDF available' : 'closes 31 Aug');
  barIn.style.width = Math.min(100, d.inn / peak * 100) + '%';
  barOut.style.width = Math.min(100, d.out / peak * 100) + '%';
