var prog = root.querySelector('.bnk3-goal-ring__prog');
var pct = root.querySelector('.bnk3-goal-ring__pct');
var amt = root.querySelector('.bnk3-goal-ring__amt');
var eta = root.querySelector('.bnk3-goal-ring__eta');
var add = root.querySelector('.bnk3-goal-ring__add');
var C = 2 * Math.PI * 52;
var saved = 1640, target = 2500, monthly = 120;
var MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var raf = null;

prog.style.strokeDasharray = C.toFixed(2);
prog.style.strokeDashoffset = C.toFixed(2);

function comma(v) { return v.toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }

function counter(to) {
  if (raf) cancelAnimationFrame(raf);
  if (reduce) { pct.textContent = Math.round(to) + '%'; return; }
  var from = parseFloat(pct.textContent) || 0;
  var t0 = 0;
  raf = requestAnimationFrame(function step(t) {
    if (!t0) t0 = t;
    var p = Math.min(1, (t - t0) / 850);
    var e = 1 - Math.pow(1 - p, 3);
    pct.textContent = Math.round(from + (to - from) * e) + '%';
    if (p < 1) raf = requestAnimationFrame(step);
  });
}

function render() {
  var frac = Math.min(1, saved / target);
  prog.style.strokeDashoffset = (C * (1 - frac)).toFixed(2);
  counter(frac * 100);
  amt.innerHTML = '£' + comma(saved) + '<span class="bnk3-goal-ring__of"> / £' + comma(target) + '</span>';
  if (saved >= target) {
    root.classList.add('bnk3-goal-ring--done');
    eta.textContent = '✓ Goal reached · ready to withdraw';
    add.disabled = true;
    add.textContent = 'Complete';
  } else {
    var months = Math.ceil((target - saved) / monthly);
    var d = new Date(2026, 7, 1);
    d.setMonth(d.getMonth() + months);
    eta.textContent = '▲ £' + monthly + '/mo · on track ' + MON[d.getMonth()] + ' ' + d.getFullYear();
  }
}

add.addEventListener('click', function () {
  saved = Math.min(target, saved + 50);
  render();
});

if (reduce) { render(); } else { requestAnimationFrame(render); }
